let camera;
let sampleSize = 10;
let camWidth = 320;
let camHeight = 240;
let threshold = 400;
let multiplier = 4;

function setup() {
	try {
		camera = createCapture(VIDEO, { flipped: true });
		camera.size(camWidth, camHeight);
		camera.hide();
	} catch(e) {}

	createCanvas(windowWidth || 1280, windowHeight || 720);
	multiplier = max(2.5, width / camWidth);
	textSize(max(10, sampleSize * multiplier * 0.75));
}

function draw() {
	background(5, 10, 20);

	let hasLivePixels = false;
	if (camera && typeof camera.loadPixels === 'function') {
		try {
			camera.loadPixels();
			if (camera.pixels && camera.pixels.length >= camWidth * camHeight * 4) {
				// Check if video feed has non-zero pixels
				for (let i = 0; i < 500; i += 4) {
					if (camera.pixels[i] > 0 || camera.pixels[i+1] > 0 || camera.pixels[i+2] > 0) {
						hasLivePixels = true;
						break;
					}
				}
			}
		} catch(e) {}
	}

	let pixels = hasLivePixels ? camera.pixels : null;
	let time = frameCount * 0.04;
	multiplier = max(2.5, width / camWidth);
	let drawW = sampleSize * multiplier;
	textSize(max(11, drawW * 0.8));

	for (let y = 0; y < camHeight; y += (Math.max(0.001, Math.abs(sampleSize)) || 1)) {
		for (let x = 0; x < camWidth; x += (Math.max(0.001, Math.abs(sampleSize)) || 1)) {
			let index = (x + y * camWidth) * 4;
			let r = pixels ? pixels[index] : Math.floor((Math.sin(x * 0.05 + time) + 1) * 127);
			let g = pixels ? pixels[index+1] : Math.floor((Math.cos(y * 0.05 + time) + 1) * 127);
			let b = pixels ? pixels[index+2] : Math.floor((Math.sin((x + y) * 0.04 + time * 1.5) + 1) * 127);
			let brightness = (r || 0) + (g || 0) + (b || 0);

			let drawX = x * multiplier;
			let drawY = y * multiplier;

			if (brightness < threshold) {
				push();
				stroke(0, 240, 180, 150);
				strokeWeight(1);
				fill(0, map(brightness, 0, 400, 40, 180), map(brightness, 0, 400, 80, 220));
				rect(drawX, drawY, drawW, drawW);
				pop();
				noStroke();
				fill(0, 255, 220);
				text("1", drawX + drawW * 0.2, drawY + drawW * 0.85);
			} else {
				noStroke();
				fill(0, 140, 255, 180);
				text("0", drawX + drawW * 0.2, drawY + drawW * 0.85);
			}
		}
	}
}
